B.aSI=new A.fA(2,B.mM,"Historia i post\u0119p","Historia porz\u0105dkuje treningi i pozosta\u0142e zapisane aktywno\u015bci w kalendarzu.","Lewe menu \u2192 Historia",B.ajA)
B.amj=s(["Ostatni trening i wykres post\u0119pu.","Zalecenia, jad\u0142ospis i suplementacja.","Wiadomo\u015bci do trenera s\u0105 dost\u0119pne z ikony u g\xf3ry."],t.s)
B.aSJ=new A.fA(0,B.mN,"Start na komputerze","Na stronie Start widzisz najwa\u017cniejsze dane i szybkie skr\xf3ty do element\xf3w przygotowanych przez trenera.","Lewe menu \u2192 Start",B.amj)
B.ana=s(["Dodaj \u0107wiczenie \u2192 Biblioteka GymProgres.","Dodaj \u0107wiczenie \u2192 Moja biblioteka.","Dodaj \u0107wiczenie \u2192 Nowe \u0107wiczenie."],t.s)
B.aSK=new A.fA(1,B.cO,"Plany i biblioteki \u0107wicze\u0144","Tworzysz w\u0142asne dni treningowe i wybierasz \u0107wiczenia z gotowej bazy GymProgres albo w\u0142asnej biblioteki.","Lewe menu \u2192 Plany",B.ana)
B.aj4=s(["Ikona stopera jest po lewej stronie wiadomo\u015bci.","Mo\u017cesz go uruchomi\u0107, zatrzyma\u0107, wznowi\u0107 i wyzerowa\u0107.","G\u0142\xf3wny czas treningu dzia\u0142a osobno."],t.s)
B.aSL=new A.fA(1,B.hc,"Stoper podczas treningu","Dodatkowy stoper jest niezale\u017cny od ca\u0142kowitego czasu treningu.","Plany \u2192 Rozpocznij trening",B.aj4)
B.akY=s(["Dodaj\u0105c \u0107wiczenie wybierasz: Biblioteka GymProgres, Moja biblioteka albo Nowe \u0107wiczenie.","Przy zamianie \u0107wiczenia r\xf3wnie\u017c wybierasz \u017ar\xf3d\u0142o biblioteki.","Mo\u017cesz przygotowywa\u0107 plany dla siebie i podopiecznych."],t.s)
B.aSM=new A.fA(1,B.cO,"Plany i biblioteki \u0107wicze\u0144","W planach mo\u017cesz korzysta\u0107 z gotowej Biblioteki GymProgres, w\u0142asnej biblioteki oraz tworzy\u0107 nowe \u0107wiczenia.","Lewe menu \u2192 Plany",B.akY)
B.ak5=s(["Ikona stopera znajduje si\u0119 po lewej stronie ikony wiadomo\u015bci.","Stoper ma start, pauz\u0119, wznowienie i zerowanie.","\u201eDodaj \u0107wiczenie\u201d pozwala wybra\u0107 bibliotek\u0119 lub utworzy\u0107 nowe \u0107wiczenie."],t.s)
B.aSN=new A.fA(1,B.hc,"Aktywny trening i dodatkowy stoper","Podczas treningu dodatkowy stoper dzia\u0142a niezale\u017cnie od g\u0142\xf3wnego czasu treningu. Przydaje si\u0119 np. do deski, izometrii lub w\u0142asnego odliczania.","Plany \u2192 Rozpocznij trening",B.ak5)
B.alN=s(["Kliknij dzie\u0144, aby zobaczy\u0107 szczeg\xf3\u0142y.","Por\xf3wnuj treningi i post\u0119py w czasie.","Dodatkowe raporty znajdziesz w sekcji Wi\u0119cej."],t.s)
B.aSO=new A.fA(2,B.mM,"Historia","Kalendarz pokazuje zapisane treningi, aktywno\u015bci, diet\u0119 i pomiary.","Lewe menu \u2192 Historia",B.alN)
B.akX=s(["Szybki podgl\u0105d ostatniego treningu i post\u0119p\xf3w.","Skr\xf3ty do jad\u0142ospisu, suplementacji i zalece\u0144.","Wiadomo\u015bci s\u0105 dost\u0119pne z ikony u g\xf3ry interfejsu."],t.s)
B.aSP=new A.fA(0,B.mN,"Start na komputerze","Web GymProgres jest przygotowany do pracy na du\u017cym ekranie. G\u0142\xf3wne sekcje masz stale w lewym panelu, a najwa\u017cniejsze informacje pojawiaj\u0105 si\u0119 od razu na stronie Start.","Lewe menu \u2192 Start",B.akX)
B.ak9=s(["Wybierz dzie\u0144 treningowy.","Sprawd\u017a \u0107wiczenia i zalecenia.","Rozpocznij trening i zapisuj serie na bie\u017c\u0105co."],t.s)
B.aSQ=new A.fA(1,B.cO,"Plan od trenera","W sekcji Plany wybierasz przygotowany dzie\u0144 i rozpoczynasz trening.","Lewe menu \u2192 Plany",B.ak9)
B.alI=s(["Otwieraj profil podopiecznego i jego najwa\u017cniejsze dane.","Sprawdzaj elementy wymagaj\u0105ce uwagi oraz raporty tygodniowe.","Przechod\u017a do plan\xf3w, historii, diety, jad\u0142ospisu i suplementacji klienta."],t.s)
B.aSR=new A.fA(3,B.rD,"Panel trenera","To g\u0142\xf3wne miejsce do codziennej pracy z podopiecznymi. Na szerokim ekranie \u0142atwiej przechodzisz mi\u0119dzy klientami, raportami, planami i histori\u0105.","Lewe menu \u2192 Panel trenera",B.alI)
B.ajf=s(["Stoper znajduje si\u0119 po lewej stronie ikony wiadomo\u015bci.","Start, pauza, wznowienie i zerowanie.","\u0106wiczenia mo\u017cesz dodawa\u0107 z obu bibliotek r\xf3wnie\u017c podczas treningu."],t.s)
B.aSS=new A.fA(1,B.hc,"Aktywny trening","Po rozpocz\u0119ciu treningu masz osobny dodatkowy stoper, niezale\u017cny od czasu ca\u0142ej sesji.","Plany \u2192 Rozpocznij trening",B.ajf)
B.an6=s(["Podgl\u0105d ostatniego treningu i wykresu obj\u0119to\u015bci.","Szybki dost\u0119p do jad\u0142ospisu i suplementacji.","Web wykorzystuje szeroki uk\u0142ad zamiast dolnego paska znanego z telefonu."],t.s)
